args <- commandArgs(trailingOnly=TRUE)
root <- if (length(args)) args[[1]] else normalizePath(file.path(dirname(sys.frame(1)$ofile), "../../.."), mustWork=FALSE)
read_csv <- function(p) read.csv(p, stringsAsFactors=FALSE, check.names=FALSE)
p <- read_csv(file.path(root,"data/processed/analysis/climate_projection_evidence.csv")); s <- read_csv(file.path(root,"data/processed/analysis/climate_scenario_sources.csv")); a <- read_csv(file.path(root,"data/processed/scenarios/climate_scenario_assumptions.csv")); h <- read_csv(file.path(root,"data/processed/scenarios/climate_scenario_hazard_states.csv")); d <- read_csv(file.path(root,"data/processed/scenarios/climate_scenario_dependency_states.csv")); r <- read_csv(file.path(root,"data/processed/scenarios/climate_scenario_resilience_states.csv")); c <- read_csv(file.path(root,"data/processed/scenarios/climate_compound_event_scenario_states.csv")); x <- read_csv(file.path(root,"outputs/figures/climate_scenario_comparison.csv"))
stopifnot(nrow(p)==12,nrow(s)==13,nrow(a)==36,nrow(h)==36,nrow(d)==48,nrow(r)==48,nrow(c)==54,nrow(x)==6)
stopifnot(length(unique(p$projection_id))==12,length(unique(s$source_id))==13,length(unique(a$assumption_id))==36,length(unique(h$state_id))==36,length(unique(d$state_id))==48,length(unique(r$state_id))==48,length(unique(c$state_id))==54)
stopifnot(all(a$scenario_id %in% c("A","B","C")), all(a$scenario_year %in% c(2050,2075)), all(h$reality_status=="fictional"),all(d$reality_status=="fictional"),all(r$reality_status=="fictional"),all(c$reality_status=="fictional"))
stopifnot(all(a$source_id %in% s$source_id),all(p$source_id %in% s$source_id),all(h$source_id %in% s$source_id),all(d$source_id %in% s$source_id),all(r$source_id %in% s$source_id),all(c$source_id %in% s$source_id))
qual <- c("high","moderate","limited","unknown"); stopifnot(all(a$plausibility %in% qual),all(a$uncertainty %in% qual),all(h$plausibility %in% qual),all(d$plausibility %in% qual),all(r$plausibility %in% qual),all(c$plausibility %in% qual)); stopifnot(all(p$observed_or_modeled %in% c("modeled_projection","model_metadata")),all(p$confidence %in% qual))
fields <- c(names(p),names(a),names(h),names(d),names(r),names(c),names(x)); stopifnot(!any(fields %in% c("hazard_score","risk_score","hazard_probability","mortality","disease_incidence","dose","social_vulnerability","outage_probability")))
text <- tolower(paste(capture.output(print(p)),capture.output(print(a)),capture.output(print(h)),capture.output(print(d)),capture.output(print(r)),capture.output(print(c)),capture.output(print(x)),collapse=" "))
stopifnot(grepl("no probability",text,fixed=TRUE),grepl("not a 2075 point estimate",text,fixed=TRUE))
for (base in c("31_climate_hazard_futures_2050","31b_climate_hazard_futures_2075")) { png <- file.path(root,"outputs/maps/systems",paste0(base,".png")); svg <- file.path(root,"outputs/maps/systems",paste0(base,".svg")); stopifnot(file.exists(png),file.info(png)$size>1000,file.exists(svg),file.info(svg)$size>1000); z <- tolower(paste(readLines(svg,warn=FALSE),collapse=" ")); for (term in c("adaptive / buffered basin","managed variable basin","compound hazard basin","not hazard zones","seiche")) stopifnot(grepl(term,z,fixed=TRUE)) }
stopifnot(file.exists(file.path(root,"reports/climate_hazard_baseline_manifest.json")),file.exists(file.path(root,"reports/climate_dependency_manifest.json")))
cat(sprintf("Phase 9C R validation passed: %d projection records, %d assumptions, %d hazard states, %d dependency states, %d resilience states, %d compound states, %d comparison rows; Maps 31/31b present\n",nrow(p),nrow(a),nrow(h),nrow(d),nrow(r),nrow(c),nrow(x)))
